"use client"

import * as m from "motion/react-m"
import type { HTMLMotionProps } from "motion/react"
import { cn } from "@/lib/utils"

const MAX_ANIMATED = 8
const STAGGER = 0.03

/**
 * Drop-in replacement for <TableRow> that fades in once.
 * Only the first 8 rows animate (30 ms stagger); the rest render immediately.
 * Opacity only — cell contents (amounts included) are never counted/animated.
 */
export function FadeRow({ index = 0, className, ...props }: HTMLMotionProps<"tr"> & { index?: number }) {
  const animated = index < MAX_ANIMATED
  return (
    <m.tr
      data-slot="table-row"
      className={cn("hover:bg-muted/50 data-[state=selected]:bg-muted border-b transition-colors", className)}
      initial={animated ? { opacity: 0 } : false}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.2, ease: "easeOut", delay: animated ? index * STAGGER : 0 }}
      {...props}
    />
  )
}

/** Same rule for card/list items (non-table lists on mobile). */
export function FadeItem({ index = 0, ...props }: HTMLMotionProps<"div"> & { index?: number }) {
  const animated = index < MAX_ANIMATED
  return (
    <m.div
      initial={animated ? { opacity: 0 } : false}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.2, ease: "easeOut", delay: animated ? index * STAGGER : 0 }}
      {...props}
    />
  )
}
