"use client"

import type React from "react"
import { MainLayout } from "@/components/main-layout"
import { AuthGuard } from "@/components/auth-guard"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import { EmptyState } from "@/components/motion/empty-state"

export function PageShell({ title, subtitle, actions, children }: { title: string; subtitle?: string; actions?: React.ReactNode; children: React.ReactNode }) {
  return (
    <AuthGuard>
      <MainLayout>
        <div className="p-3 sm:p-4 md:p-6 lg:p-8">
          <div className="mx-auto max-w-7xl space-y-4 sm:space-y-6">
            <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
              <div className="space-y-1">
                <h2 className="text-xl font-bold tracking-tight sm:text-2xl lg:text-3xl">{title}</h2>
                {subtitle && <p className="text-sm text-muted-foreground sm:text-base">{subtitle}</p>}
              </div>
              {actions && <div className="flex flex-wrap gap-2">{actions}</div>}
            </div>
            {children}
          </div>
        </div>
      </MainLayout>
    </AuthGuard>
  )
}

export function Stat({ title, value, hint, icon: Icon, tone }: { title: string; value: React.ReactNode; hint?: React.ReactNode; icon?: any; tone?: "good" | "bad" | "warn" | "muted" }) {
  const color = tone === "good" ? "text-positive" : tone === "bad" ? "text-negative" : tone === "warn" ? "text-foreground" : ""
  return (
    <Card className="overflow-hidden">
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-xs font-medium text-muted-foreground sm:text-sm line-clamp-2">{title}</CardTitle>
        {Icon && <Icon className="h-4 w-4 shrink-0 text-muted-foreground" />}
      </CardHeader>
      <CardContent className="space-y-1">
        <div className={cn("text-lg font-bold sm:text-2xl tabular-nums", color)}>{value}</div>
        {hint && <p className="text-xs text-muted-foreground line-clamp-2">{hint}</p>}
      </CardContent>
    </Card>
  )
}

export function Empty({ text }: { text: string }) {
  return <EmptyState text={text} />
}

export function Field({ label, children, className }: { label: string; children: React.ReactNode; className?: string }) {
  return (
    <label className={cn("grid gap-1.5 text-sm", className)}>
      <span className="font-medium">{label}</span>
      {children}
    </label>
  )
}
